import {scenarioAllowsBackground} from './scenario-background-rules.js?v=garbage-health-1';
import {recordHazard} from './emergency-order.js?v=garbage-health-1';
import {beginEmergencySession} from './emergency-session.js?v=garbage-health-1';
export const freshSpaceJunk=()=>({randomSpaceJunk:false,spaceJunk:null,spaceJunkFalls:0,spaceJunkImpacts:0});
export function startSpaceJunk(c,x,y){const n=Math.sqrt(c.tiles.length),e=c.emergency;if(e.spaceJunk)return{ok:false,error:'This disaster type is already active.'};if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x>=n||y>=n)return{ok:false,error:'Choose a tile inside the city.'};beginEmergencySession(c);recordHazard(e,'spaceJunk');Object.assign(e,{spaceJunk:{x,y,originX:x,originY:y,age:0}});e.spaceJunkFalls++;return{ok:true};}
export function stepSpaceJunk(c,impact){const e=c.emergency,s=e.spaceJunk;if(!s)return 0;s.age++;if(s.age%4)return 0;const damage=impact(c,s.x,s.y);e.spaceJunkImpacts++;if(s.age===24){e.spaceJunk=null;return damage;}const n=Math.sqrt(c.tiles.length),k=s.age/4;let seed=Math.imul(c.seed+e.spaceJunkFalls,1664525)^Math.imul(k,1013904223);const dx=((seed>>>0)%13)-6,dy=(((seed>>>8)>>>0)%13)-6;s.x=Math.max(0,Math.min(n-1,s.originX+dx));s.y=Math.max(0,Math.min(n-1,s.originY+dy));return damage;}
export function validateSpaceJunk(v,n,version){if(version<42)return freshSpaceJunk();if(version>=43&&typeof v.randomSpaceJunk!=='boolean')throw Error('Invalid random space junk setting.');if(['spaceJunkFalls','spaceJunkImpacts'].some(k=>!Number.isInteger(v[k])||v[k]<0||v[k]>1e9)||v.spaceJunkImpacts>v.spaceJunkFalls*6)throw Error('Invalid space junk history.');let spaceJunk=null;if(v.spaceJunk!==null){const s=v.spaceJunk;if(!s||!v.active||(version<96&&(v.riot||v.locust||v.tornado||v.earthquake))||!v.spaceJunkFalls||!Number.isInteger(s.age)||s.age<0||s.age>=24||['x','y','originX','originY'].some(k=>!Number.isInteger(s[k])||s[k]<0||s[k]>=n))throw Error('Invalid falling space junk.');spaceJunk={x:s.x,y:s.y,originX:s.originX,originY:s.originY,age:s.age};}return{randomSpaceJunk:version>=43?v.randomSpaceJunk:false,spaceJunk,spaceJunkFalls:v.spaceJunkFalls,spaceJunkImpacts:v.spaceJunkImpacts};}

export function setRandomSpaceJunk(c,value){if(c.emergency.active)return{ok:false,error:'Finish the active emergency before changing disaster settings.'};if(typeof value!=='boolean')return{ok:false,error:'Choose a valid space junk setting.'};c.emergency.randomSpaceJunk=value;return{ok:true};}
const roll=(month,seed,salt)=>{let h=Math.imul(month+salt,374761393)^Math.imul(seed+71,668265263);h=Math.imul(h^(h>>>13),1274126177);return((h^(h>>>16))>>>0)/4294967296;};
export function maybeSpaceJunk(c){if(!scenarioAllowsBackground(c,'randomDisasters'))return false;if(!c.emergency.randomSpaceJunk||c.emergency.active||roll(c.month,c.seed,97)>=.003)return false;const n=Math.sqrt(c.tiles.length);return startSpaceJunk(c,Math.floor(roll(c.month,c.seed,101)*n),Math.floor(roll(c.month,c.seed,107)*n)).ok;}
